import { writeFile } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";

const CELL_COUNT = parsePositiveInteger(optionValue("--count") || process.env.LARGE_EXAMPLE_CELLS, 1024);
const pair = process.argv.includes("--pair");
const outputPath = optionValue("--output");
const outputUrl = outputPath
  ? pathToFileURL(outputPath)
  : new URL("../examples/large_buffer_chain_1024.v", import.meta.url);
const moduleNames = pair
  ? ["large_compare_left_1024", "large_compare_right_1024"]
  : ["large_buffer_chain_1024"];
const lines = [
  "// Generated by tools/generate-large-example.mjs. Do not edit manually.",
  pair
    ? "// Stage 8 browser fixture: two independent 1024-cell modules for Compare Search-first."
    : "// Stage 4 smoke example: 1024-cell deep buffer chain."
];

for (const moduleName of moduleNames) {
  lines.push(...createBufferChain(moduleName, CELL_COUNT), "");
}
await writeFile(outputUrl, lines.join("\n"), "utf8");
console.log(`Generated ${fileURLToPath(outputUrl)} with ${CELL_COUNT * moduleNames.length} cells across ${moduleNames.length} module(s)`);

function createBufferChain(moduleName, cellCount) {
  const lines = [
    `module ${moduleName} (clk, data_in, data_out);`,
    "input clk;",
    "input data_in;",
    "output data_out;",
    `wire ${Array.from({ length: cellCount - 1 }, (_, index) => `n${index}`).join(", ")};`,
    ""
  ];
  for (let index = 0; index < cellCount; index += 1) {
    const input = index === 0 ? "data_in" : `n${index - 1}`;
    const output = index === cellCount - 1 ? "data_out" : `n${index}`;
    lines.push(`BUF_X1 u_buf_${index} (.A(${input}), .Z(${output}));`);
  }
  return [...lines, "endmodule"];
}

function optionValue(name) {
  const prefix = `${name}=`;
  const argument = process.argv.find((item) => item.startsWith(prefix));
  return argument ? argument.slice(prefix.length) : null;
}

function parsePositiveInteger(value, fallback) {
  const number = Number(value);
  return Number.isInteger(number) && number > 0 ? number : fallback;
}
